#!/usr/bin/env bash
# Fixes "Kiosk Process Status: Unknown (no heartbeat yet)" staying stuck
# forever even on a fully working instance (confirmed on Ewan: app
# running, v1.0.1 installed and passing its update-flow health check,
# heartbeats arriving normally - just this one field never filling in).
#
# The Admin Panel side was already fully built and waiting:
# Instance.kiosk_process_status, app/blueprints/agent_api.py's heartbeat
# handler reading data.get("kiosk_process_status"), and
# app/templates/instances/detail.html rendering all four states
# (running/stopped/not_configured/giving_up) - agent/heartbeat.py just
# never actually sent it. Fixed by mapping ProcessSupervisor.status() onto
# those exact four strings and including it in every heartbeat.
#
# Verified: all four states map correctly (not_configured for no/
# unconfigured supervisor, stopped for configured-but-not-running, running
# for a real live process, giving_up via a mocked status), and a full
# end-to-end test against a live server with a real running subprocess
# confirms kiosk_process_status="running" actually lands in the database
# after a real heartbeat call.
#
# Run from inside /root/admin_panel.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in agent requirements.txt service_files; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run this from the admin_panel repo root."
        exit 1
    fi
done

echo "==> Extracting fixed agent/ into this repo"
TMP_EXTRACT="$(mktemp -d)"
base64 -d > "$TMP_EXTRACT/opslab-agent.tar.gz" << 'AGENT_TAR_EOF_MARKER'

AGENT_TAR_EOF_MARKER
tar -xzf "$TMP_EXTRACT/opslab-agent.tar.gz" -C "$TMP_EXTRACT"

if ! grep -q "_kiosk_process_status" "$TMP_EXTRACT/agent/heartbeat.py"; then
    echo "    ERROR: fix not found in the extracted agent payload!"
    rm -rf "$TMP_EXTRACT"
    exit 1
fi

rm -f agent/config.py.bak
cp -f "$TMP_EXTRACT/agent/"*.py agent/
echo "    Updated agent/*.py in this repo."

echo "==> Rewriting app/static/installers/opslab-agent.tar.gz (served by /install.ps1)"
cp -f "$TMP_EXTRACT/opslab-agent.tar.gz" app/static/installers/opslab-agent.tar.gz
rm -rf "$TMP_EXTRACT"

echo "==> Verifying"
tar -tzf app/static/installers/opslab-agent.tar.gz > /dev/null && echo "    served agent tarball is readable"

echo ""
echo "Done. On Ewan, re-enroll once more to pick this up:"
echo "    irm https://kiosksys.opslabsystems.cloud/install.ps1 -OutFile install.ps1; .\\install.ps1 -Token <fresh-token> -AdminUrl https://kiosksys.opslabsystems.cloud"
echo ""
echo "After the next heartbeat (within ~30-60s of it registering), 'Kiosk Process"
echo "Status' should read 'Running' instead of 'Unknown'."
